        fn_boardCheck(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05100.ipt_searchWord_onkeyup' }); }
};

/**
 * @event
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 09. 29
